// Which accounts to run, and under what label. Webhook body can pass {"limit": N, "run_label": "..."}.
let body = {};
try { body = $('Run from outside (webhook)').first().json.body || {}; } catch (e) {}
const limit = Number(body.limit) || null;
const run_label = body.run_label || 'waterfall_v1';
let rows = $input.all().map(i => ({ ...i.json, run_label }));
if (limit) rows = rows.slice(0, limit);
return rows.map(json => ({ json }));

// STEP 1 result: start this account's "profile" from what we already know and is still fresh (field_ttl).
const a = $('One at a time').item.json;
const c = (typeof $json === 'object' && $json && !Array.isArray($json)) ? $json : {};
const known = ['employee_count','industry','linkedin_url','phone','contact_email','contact_name'].filter(k => c[k] != null);
return { json: {
  company_key: a.company_key, company_name: a.company_name, domain: a.domain, run_label: a.run_label,
  employee_count: c.employee_count ?? null, industry: c.industry ?? null, linkedin_url: c.linkedin_url ?? null,
  phone: c.phone ?? null, contact_email: c.contact_email ?? null, contact_name: c.contact_name ?? null,
  contact_title: null, pattern: null,
  steps: [{ provider: 'cache', matched: known.length > 0, credits_used: 0,
            fields: Object.fromEntries(known.map(k => [k, c[k]])), error: null }]
}};

// STEP 2 (free): read the company's own website (home, /about, /contact, /team) for emails, LinkedIn page, phone.
// Polite: 4 pages max, identifies itself, and stops if the site blocks us (403/429/503) - no bypassing.
const p = { ...$json, steps: [...$json.steps] };
const ROLE = /^(info|sales|support|hello|contact|admin|office|team|careers|jobs|hr|marketing|billing|accounts|help|enquiries|inquiries|noreply|no-reply|press|partners|founders)@/i;
const needEmail = !p.contact_email || ROLE.test(p.contact_email);
if (!(needEmail || !p.linkedin_url || !p.phone)) return { json: p };      // nothing missing that a website could give

const root = String(p.domain).toLowerCase().replace(/^www\./, '');
const found = { emails: new Set(), linkedin: null, phone: null };
let pages = 0, error = null;
for (const path of ['', '/about', '/contact', '/team']) {
  try {
    let html = String(await this.helpers.httpRequest({ method: 'GET', url: 'https://' + root + path, timeout: 8000, json: false,
      headers: { 'User-Agent': 'Mozilla/5.0 (compatible; gtm-icp-engine research; +https://github.com/knife-co/gtm-icp-engine)' } }) || '');
    pages++;
    html = html.replace(/\\u00[0-9a-f]{2}/gi, ' ').replace(/%[0-9a-f]{2}/gi, ' ');   // clean escaped characters before looking for emails
    for (const m of html.matchAll(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/gi)) {
      const e = m[0].toLowerCase(), dom = e.split('@')[1];
      if (/\.(png|jpe?g|gif|svg|webp)$/.test(e)) continue;
      if (dom === root || dom.endsWith('.' + root)) found.emails.add(e);
    }
    if (!found.linkedin) { const m = html.match(/https?:\/\/(?:[a-z]{2,3}\.)?linkedin\.com\/company\/[A-Za-z0-9_\-%.]+/i); if (m) found.linkedin = m[0].replace(/[\/.]+$/, ''); }
    if (!found.phone) { const m = html.match(/href=["']tel:([^"']+)["']/i); if (m) found.phone = decodeURIComponent(m[1]).trim(); }
  } catch (e) {
    const code = Number(e.httpCode || e.statusCode || (e.response && e.response.status));
    if ([403, 429, 503].includes(code)) { error = 'site blocked us (' + code + '), not bypassed'; break; }
  }
}
const fields = {};
const emails = [...found.emails];
const personal = emails.find(e => !ROLE.test(e));
const pick = personal || emails[0];
if (pick && needEmail && (!p.contact_email || (personal && ROLE.test(p.contact_email)))) { p.contact_email = pick; fields.contact_email = pick; }
if (!p.linkedin_url && found.linkedin) { p.linkedin_url = found.linkedin; fields.linkedin_url = found.linkedin; }
if (!p.phone && found.phone) { p.phone = found.phone; fields.phone = found.phone; }
p.steps.push({ provider: 'website', matched: Object.keys(fields).length > 0, credits_used: 0, fields,
               error: error || (pages === 0 ? 'site unreachable' : null) });
return { json: p };

// Only call Hunter if we still have no PERSONAL email, and the breaker/budget says 'try'.
const p = $('Step 2 · Website').item.json;
const ROLE = /^(info|sales|support|hello|contact|admin|office|team|careers|jobs|hr|marketing|billing|accounts|help|enquiries|inquiries|noreply|no-reply|press|partners|founders)@/i;
const answer = String($json.data || '').replace(/"/g, '');
const needEmail = !p.contact_email || ROLE.test(p.contact_email);
return { json: { ...p, _call: needEmail && answer === 'try', _breaker: answer } };

// Read Hunter's domain search: best personal email (GTM-ish titles first), the company's email pattern, firmographics.
const p = { ...$('Call Hunter?').item.json, steps: [...$('Call Hunter?').item.json.steps] };
const r = $json || {};
const step = { provider: 'hunter', matched: false, credits_used: 0, fields: {}, error: null };
let rec = { p: 'hunter', ok: true, err: null, used: 0 };
if (r.data && (r.data.domain || r.data.emails)) {
  const d = r.data; rec.used = 1; step.credits_used = 1;
  const gtm = t => /(rev ?ops|revenue|sales|marketing|growth|gtm|crm|operations|founder|ceo|head|vp|director)/i.test(t || '') ? 1 : 0;
  const emails = d.emails || [];
  const best = emails.filter(e => e.type === 'personal').sort((a, b) => (gtm(b.position) - gtm(a.position)) || ((b.confidence || 0) - (a.confidence || 0)))[0] || emails[0];
  if (best) {
    p.contact_email = best.value; p.contact_name = [best.first_name, best.last_name].filter(Boolean).join(' ') || null;
    p.contact_title = best.position || null;
    Object.assign(step.fields, { contact_email: p.contact_email, contact_name: p.contact_name, contact_title: p.contact_title });
  }
  if (d.pattern) p.pattern = d.pattern;
  if (!p.industry && d.industry) { p.industry = d.industry; step.fields.industry = d.industry; }
  if (!p.employee_count && d.headcount) { const n = parseInt(String(d.headcount).match(/\d+/)?.[0] || '', 10); if (n) { p.employee_count = n; step.fields.employee_count = n; } }
  if (!p.linkedin_url && d.linkedin) { p.linkedin_url = d.linkedin; step.fields.linkedin_url = d.linkedin; }
  step.matched = Object.keys(step.fields).length > 0;
} else if (r.error || r.errors) {
  rec = { p: 'hunter', ok: false, err: JSON.stringify(r.error || r.errors).slice(0, 300), used: 1 };
  step.error = rec.err; step.credits_used = 1;
} else {
  step.error = 'Hunter not connected yet (node switched off)';
}
p.steps.push(step); p._record = rec;
return { json: p };

// Only call Apollo (costs 1 credit) if size, industry or LinkedIn page is still missing, and the breaker/budget says 'try'.
const p = $('Profile after Hunter').item.json;
const answer = String($json.data || '').replace(/"/g, '');
const need = !p.employee_count || !p.industry || !p.linkedin_url;
return { json: { ...p, _call: need && answer === 'try', _breaker: answer } };

const p = { ...$('Call Apollo?').item.json, steps: [...$('Call Apollo?').item.json.steps] };
const r = $json || {};
const step = { provider: 'apollo', matched: false, credits_used: 0, fields: {}, error: null };
let rec = { p: 'apollo', ok: true, err: null, used: 0 };
if (r.organization) {
  const o = r.organization; rec.used = r.replayed ? 0 : 1; step.credits_used = 1;   // replayed answers still COUNT as 1 credit, but don't use up the real budget
  const set = (k, v) => { if (!p[k] && v != null) { p[k] = v; step.fields[k] = v; } };
  set('employee_count', o.estimated_num_employees);
  set('industry', o.industry);
  set('linkedin_url', o.linkedin_url);
  set('phone', o.primary_phone?.number ?? o.phone ?? null);
  step.matched = true;
} else if (r.error || r.errors) {
  rec = { p: 'apollo', ok: false, err: JSON.stringify(r.error || r.errors).slice(0, 300), used: 0 };
  step.error = rec.err;
} else if (r.steps) {
  step.error = 'Apollo not connected yet (node switched off)';
} else {
  step.error = 'no match';                       // Apollo answered but did not know this company: 0 credits
}
p.steps.push(step); p._record = rec;
return { json: p };

// STEP 5 (free): if we know the company's email pattern (from Hunter) and a person's name but no personal email,
// build the address from the pattern. Always labelled 'unverified' - a guess is not a fact.
const p = { ...$json, steps: [...$json.steps] };
const ROLE = /^(info|sales|support|hello|contact|admin|office|team|careers|jobs|hr|marketing|billing|accounts|help|enquiries|inquiries|noreply|no-reply|press|partners|founders)@/i;
const needEmail = !p.contact_email || ROLE.test(p.contact_email);
const [first, ...rest] = String(p.target_name || '').trim().split(/\s+/);
const last = rest.pop();
if (needEmail && p.pattern && first && last) {
  const f = first.toLowerCase(), l = last.toLowerCase();
  const local = p.pattern.replace('{first}', f).replace('{last}', l).replace('{f}', f[0]).replace('{l}', l[0]);
  p.contact_email = local + '@' + String(p.domain).replace(/^www\./, '');
  p.steps.push({ provider: 'pattern', matched: true, credits_used: 0, fields: { contact_email: p.contact_email, contact_name: p.target_name }, error: null });
}
return { json: p };

// One row per step that ran, so we can see WHICH source supplied WHAT, and what it cost.
const p = $json;
const rows = p.steps.map(s => ({
  run_label: p.run_label, company_key: p.company_key, provider: s.provider, matched: !!s.matched,
  employee_count: s.fields.employee_count ?? null, industry: s.fields.industry ?? null,
  linkedin_url: s.fields.linkedin_url ?? null, phone: s.fields.phone ?? null,
  contact_name: s.fields.contact_name ?? null, contact_title: s.fields.contact_title ?? null,
  contact_email: s.fields.contact_email ?? null, credits_used: s.credits_used || 0, raw: null, error: s.error ?? null }));
return { json: { rows } };
